.combatant-nameplate { font-family: var(--mono); font-size: 8px; letter-spacing: 0.12em; text-transform: uppercase; color: rgba(238,230,207,0.62); background: rgba(6,10,11,0.55); padding: 2px 7px; border-radius: 99px; border: 1px solid rgba(255,255,255,0.08); }

.battle-fx-layer { position: absolute; inset: 0; z-index: 6; pointer-events: none; overflow: hidden; }
.battle-fx {
  position: absolute; font-family: var(--mono); font-weight: 800; font-size: 24px;
  color: #fff; text-shadow: 0 2px 0 #000, 0 0 16px rgba(255,255,255,0.4);
  animation: fx-rise 0.9s ease-out forwards;
  transform: translate(-50%, -50%);
}
.battle-fx.damage { color: #ffb3a1; }
.battle-fx.crit { color: var(--gold); font-size: 32px; }
.battle-fx.heal { color: #9ff0a8; }
.battle-fx.eff { color: var(--gold); font-size: 16px; letter-spacing: 0.04em; text-shadow: 0 2px 0 #000; }
.battle-fx.status { color: var(--purple); font-size: 15px; }
.battle-fx.miss { color: #b9c4cf; font-size: 16px; }

.battle-move-banner {
  position: absolute; z-index: 7; left: 50%; top: 44%; transform: translate(-50%, -50%);
  padding: 7px 18px; border-radius: 99px;
  font-family: var(--mono); font-size: 13px; font-weight: 800; letter-spacing: 0.08em;

.battle-stage { position: relative; flex: 1 1 auto; min-height: 260px; overflow: hidden; }
.battle-horizon {
  position: absolute; left: 0; right: 0; bottom: 26%; height: 1px;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.13), transparent);
}
.battle-ground {
  position: absolute; left: -10%; right: -10%; bottom: -18%; height: 62%;
  background: radial-gradient(ellipse at center, color-mix(in srgb, var(--battle-ground, #2f6b3d) 55%, transparent), transparent 70%);
  filter: blur(4px); opacity: 0.65;
}
.battle-platform {
  position: absolute; width: 190px; height: 52px; border-radius: 50%;
  background: radial-gradient(ellipse at center, rgba(0,0,0,0.55), transparent 70%);
  filter: blur(2px);
}
.battle-platform.enemy { right: 8%; top: 46%; transform: rotate(-3deg); }
.battle-platform.player { left: 8%; bottom: 12%; transform: rotate(2deg); }

.battle-card {
  position: absolute; z-index: 4;
  width: min(330px, 38vw);
  padding: 10px 12px;
  border: 1px solid rgba(255,255,255,0.14); border-radius: 11px;
  background: linear-gradient(180deg, rgba(16,26,27,0.92), rgba(8,14,15,0.92));
  box-shadow: 0 10px 26px rgba(0,0,0,0.4);
  backdrop-filter: blur(8px);
}
.battle-card.enemy-card { left: 18px; top: 18px; }
.battle-card.player-card { right: 18px; bottom: 18px; }
.battle-name-row { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; margin-bottom: 5px; }
.battle-name-row strong { font-size: 14px; letter-spacing: 0.01em; }
.battle-name-row .battle-lv { font-family: var(--mono); font-size: 9px; color: var(--gold); }
.battle-hp { display: flex; flex-direction: column; gap: 3px; }
.battle-hp-track { position: relative; height: 9px; border-radius: 99px; background: rgba(0,0,0,0.55); border: 1px solid rgba(255,255,255,0.1); overflow: hidden; }
.battle-hp-fill { height: 100%; width: 100%; border-radius: 99px; background: linear-gradient(180deg, #8fe0a7, #4cbf83); transition: width 0.5s cubic-bezier(.2,.8,.2,1), background 0.3s; }
.battle-hp-fill.warn { background: linear-gradient(180deg, #ffe39b, #e5b948); }
.battle-hp-fill.bad { background: linear-gradient(180deg, #ffabab, #d95656); }
.battle-hp-text { display: flex; justify-content: space-between; font-family: var(--mono); font-size: 8.5px; color: var(--muted); }
.battle-hp-text strong { color: var(--ink-soft); font-weight: 500; }
.battle-meta { display: flex; align-items: center; flex-wrap: wrap; gap: 5px; margin-top: 5px; }
.battle-energy { display: flex; align-items: center; gap: 5px; font-family: var(--mono); font-size: 8px; color: var(--muted); margin-top: 5px; }
.battle-energy-track { flex: 1; height: 3px; border-radius: 99px; background: rgba(0,0,0,0.4); overflow: hidden; }
.battle-energy-fill { height: 100%; border-radius: 99px; background: linear-gradient(90deg, #6d9cff, #9fdff0); transition: width 0.35s ease; }

.combatant { position: absolute; z-index: 3; display: flex; flex-direction: column; align-items: center; gap: 4px; transition: filter 0.2s, opacity 0.3s, transform 0.2s; }
